using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9: ZipArchiveEntry now sets the UTF-8 flag by default.
        // The legacy Java consumer expects Shift-JIS filenames, so we
        // must open with an explicit Shift-JIS encoding to suppress
        // the UTF-8 flag and encode entry names in Shift-JIS.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        var shiftJis = Encoding.GetEncoding("Shift-JIS");
        using var stream = new FileStream("data.zip", FileMode.Create);
        using var archive = new ZipArchive(stream, ZipArchiveMode.Create, leaveOpen: false, entryNameEncoding: shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9: [FromKeyedServices] no longer falls back to non-keyed
// registrations — register as keyed to match the controller attribute.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

